using System.Text.Json;
using System.IO;
using VisionCore;
using VisionFramework;
using VisionEditor.Core;
using VisionPluginContracts;
int checks=0;void Check(bool valid,string message){if(!valid)throw new Exception(message);checks++;}
var registry=new ModuleRegistry();
registry.Register(new("source","1","source",[],[new("Position",DataKind.Point),new PortDescriptor("Points",DataKind.Point){Cardinality=ValueCardinality.Array},new("OtherX",DataKind.Number)],[]),()=>new Source());
registry.Register(new("sink","1","sink",[new("Point",DataKind.Point,false),new("X",DataKind.NumberArray,false),new("Y",DataKind.NumberArray,false)],[new("X",DataKind.NumberArray),new("Y",DataKind.NumberArray)],[]),()=>new Sink());
var document=new GraphEditorDocument(registry);var source=document.AddNode("source","1",0,0);var target=document.AddNode("sink","1",200,0);document.ConnectExecution(source,target);string procedure=document.CurrentProcedureId;
ProcedureDocument Flow()=>document.Document.Procedures.Single(p=>p.Id==procedure);
bool reject=false;int batchWrites=0;
var basic=new WorkflowConfigurationSubscriptionService(Flow,registry,target,(d,r)=>document.SetProcedureInputSubscription(procedure,target,d.Name,r),changes=>{if(reject)throw new InvalidOperationException("Host rejected batch");batchWrites++;document.SetProcedureInputSubscriptions(procedure,target,changes.ToDictionary(c=>c.Destination.Name,c=>c.Source));});
var aliases=new PointAliasConfigurationSubscriptions(basic,Flow,registry,target,[new("Point","X","Y")]);
var combined=new ConfigurationSubscriptionDestination(ConfigurationSubscriptionDomain.Combination,"Point","POINT");var x=new ConfigurationSubscriptionDestination(ConfigurationSubscriptionDomain.InputIo,"X","float");var y=x with{Name="Y"};
ConfigurationSubscriptionBinding Output(string port,string native)=>new(new ConfigurationOutputReference(procedure,source,port,native),ConfigurationSubscriptionIndex.All);
var tree=aliases.Enumerate(new(combined,["POINT"]));Check(tree.Status==ConfigurationSubscriptionStatus.Available&&tree.Roots.SelectMany(r=>r.Children).Count()==2,"POINT query exposes actual scalar and array sources through component capability");
long before=document.Revision;var point=Output("Position","POINT");Check(aliases.Bind(combined,point).Status==ConfigurationSubscriptionStatus.Available,"complete POINT binds both stored components");Check(document.Revision==before+1&&batchWrites==1,"complete point binding is one managed undo transaction");
Check(Flow().Configuration.Subscriptions.Count==2&&Flow().Configuration.Subscriptions.All(s=>s.Target!="Point"),"single authority is the X/Y leaf subscriptions");
Check(aliases.Read(x).Binding==Output("Position.X","float")&&aliases.Read(y).Binding==Output("Position.Y","float"),"mode switch reads same typed component sources");Check(aliases.Read(combined).Binding==point,"complete matching leaves reconstruct common POINT identity");
var run=await new GraphExecutor(registry).RunAsync(Flow(),Directory.GetCurrentDirectory());var nodeResult=run.Nodes.Single(n=>n.NodeId==target);Check(nodeResult.Status==NodeRunStatus.Success&&nodeResult.Outputs["X"].As<IReadOnlyList<double>>().Single()==10&&nodeResult.Outputs["Y"].As<IReadOnlyList<double>>().Single()==20,"real graph expands point fields and consumes one authority");
Check(aliases.Bind(x,Output("OtherX","float")).Status==ConfigurationSubscriptionStatus.Available,"single X override accepted");var tuple=aliases.Read(combined);Check(tuple.ReadOnly&&tuple.Binding?.Reference is ConfigurationPointTupleReference,"mixed leaves show a read-only typed tuple");Check(aliases.Read(y).Binding==Output("Position.Y","float"),"single X override preserves Y source");
run=await new GraphExecutor(registry).RunAsync(Flow(),Directory.GetCurrentDirectory());nodeResult=run.Nodes.Single(n=>n.NodeId==target);Check(nodeResult.Outputs["X"].As<IReadOnlyList<double>>().Single()==99&&nodeResult.Outputs["Y"].As<IReadOnlyList<double>>().Single()==20,"actual graph honors changed X and original Y");
reject=true;before=document.Revision;Check(aliases.Bind(combined,point).Status==ConfigurationSubscriptionStatus.Failed&&document.Revision==before,"rejected batch cannot fake success or mutate undo history");Check(aliases.Read(x).Binding==Output("OtherX","float"),"rejected managed transaction preserves accepted leaf");reject=false;
var array=Output("Points","POINT");Check(aliases.Bind(combined,array).Status==ConfigurationSubscriptionStatus.Available,"array POINT projects to numeric vector leaf transport");run=await new GraphExecutor(registry).RunAsync(Flow(),Directory.GetCurrentDirectory());nodeResult=run.Nodes.Single(n=>n.NodeId==target);Check(nodeResult.Outputs["X"].As<IReadOnlyList<double>>().SequenceEqual(new[]{1d,3})&&nodeResult.Outputs["Y"].As<IReadOnlyList<double>>().SequenceEqual(new[]{2d,4}),"point array component order survives actual graph execution");
document.Undo();Check(aliases.Read(x).Binding==Output("OtherX","float"),"single undo restores both prior leaf sources");document.Redo();Check(aliases.Read(combined).Binding==array,"redo restores array combination");
var saved=Path.GetFullPath("analysis/full-audit/point-alias/alias.vmx");Directory.CreateDirectory(Path.GetDirectoryName(saved)!);document.Save(saved);var loaded=new GraphEditorDocument(registry);loaded.Load(saved);Check(loaded.CurrentProcedure.Configuration.Subscriptions.Count==2,"leaf authority survives workflow persistence");
Check(aliases.Bind(combined,null).Status==ConfigurationSubscriptionStatus.Available&&aliases.Read(x).Binding is null&&aliases.Read(y).Binding is null,"clear combination clears both leaves");
document.SetProcedureInputSubscription(procedure,target,"Point",new(WorkflowSourceKind.NodeOutput,source,"Position"));Check(aliases.Read(x).Binding==Output("Position.X","float"),"legacy standalone POINT binding gets typed component readback");Check(aliases.Bind(x,Output("OtherX","float")).Status==ConfigurationSubscriptionStatus.Available&&Flow().Configuration.Subscriptions.All(s=>s.Target!="Point"),"editing a legacy component migrates it to leaf authority");Check(aliases.Read(y).Binding==Output("Position.Y","float"),"legacy migration preserves unchanged Y");
before=document.Revision;Check(aliases.Bind(combined,Output("Position","float")).Status!=ConfigurationSubscriptionStatus.Available&&document.Revision==before,"forged native type cannot become POINT");
var wrongIndex=new ConfigurationSubscriptionBinding(point.Reference,ConfigurationSubscriptionIndex.At(1));Check(aliases.Bind(combined,wrongIndex).Status==ConfigurationSubscriptionStatus.Unsupported,"unsupported indexing is explicit and leaves accepted binding");
var bad=basic.BindMany([new(x,Output("Position.X","float")),new(y,Output("missing","float"))]);Check(bad.Status!=ConfigurationSubscriptionStatus.Available&&document.Revision==before,"second leaf validation failure does not partially apply managed transaction");
Console.WriteLine($"PASS {checks} POINT alias/persistence/graph checks");
sealed class Source:IModule {public ModuleDescriptor Descriptor=>new("source","1","source",[],[new("Position",DataKind.Point),new PortDescriptor("Points",DataKind.Point){Cardinality=ValueCardinality.Array},new("OtherX",DataKind.Number)],[]);public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"Position",PortValue.Point(new(10,20))},{"Points",PortValue.PointArray(new[]{new Point2(1,2),new Point2(3,4)})},{"OtherX",PortValue.Number(99)}}));}
sealed class Sink:IModule {public ModuleDescriptor Descriptor=>new("sink","1","sink",[new("Point",DataKind.Point,false),new("X",DataKind.NumberArray,false),new("Y",DataKind.NumberArray,false)],[new("X",DataKind.NumberArray),new("Y",DataKind.NumberArray)],[]);public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"X",c.Inputs["X"]},{"Y",c.Inputs["Y"]}}));}
